commit 7ce3e77dfbca80bfa2ab3c73a84e0454570d7158
Author: Colin McDonnell <3084745+colinhacks@users.noreply.github.com>
Date:   Mon Aug 24 22:51:20 2026 -0700

    fix(v4): run a wrapper's inner schema on its own payload (#6462)

    A pipe hands its `out` schema the caller's issues array, so an unrecognized key can survive to an enclosing intersection that may yet reconcile it. Two wrappers on the far side of that pipe read someone else's issue as their own inner failing, substituted for it, and cleared the array.

    For `.catch()` that lost the strict violation, and where an intersection was the reason the key was forwarded at all, it substituted the fallback into one side of the merge and threw `Unmergable intersection` out of `safeParse`. `.optional()` over a defaulted inner had the same hole. Neither wrapper had any business substituting: `z.any()` cannot fail and a default cannot fail.

    Both fired because they shared a payload with their inner schema and so could not tell whose issues they were looking at. The inner now gets a payload of its own, as it did in v3 and as the compiled path already did. Everything that existed to undo the inner's damage to the shared payload goes with it — the pre-run value capture, the defensive copy of the issues array, and the truncation and abort resets in both wrappers. `issues.length = 0` no longer appears anywhere in `core/`.

    One flag is carried across by hand. The memoizer marks a payload whose value is a node still being parsed, and that mark describes the value, which still propagates. Without it an enclosing readonly froze a half-built object — silently dropping a key under the JIT, and throwing `TypeError` out of `parse` for records, tuples, arrays and jitless objects — and a check on the back-edge ran against the in-progress node.

    Bundle is 2 B smaller raw and 5 B smaller gzipped on a classic fixture, unchanged on `zod/mini`. Retained bytes per schema are identical, and failure-path allocation drops about 24 B per parse with no measurable change on the success path.

    Refs #6192

diff --git a/packages/zod/src/v4/classic/tests/catch.test.ts b/packages/zod/src/v4/classic/tests/catch.test.ts
index cbc22f6c..dd53c441 100644
--- a/packages/zod/src/v4/classic/tests/catch.test.ts
+++ b/packages/zod/src/v4/classic/tests/catch.test.ts
@@ -308,6 +308,81 @@ test("catch ctx carries the rest of the payload through", () => {
   expect(seen.aborted).toBe(true);
 });

+test("catch does not swallow an issue it did not cause", () => {
+  // A pipe hands its `out` schema the caller's issues array so an unrecognized key can survive to an enclosing intersection. The catch must not read that as its own inner failing.
+  const result = z.strictObject({ a: z.string() }).pipe(z.any().catch("CAUGHT")).safeParse({ a: "x", extra: 1 });
+
+  expect(result.success).toBe(false);
+  expect(result.error!.issues.map((i) => i.code)).toEqual(["unrecognized_keys"]);
+});
+
+test("catch does not break intersection reconciliation", () => {
+  // Forwarding the unrecognized key is what lets the intersection reconcile it. A catch that fired on it substituted its fallback into one side, and the merge threw out of safeParse.
+  const schema = z.intersection(
+    z.strictObject({ a: z.string() }).pipe(z.any().catch("CAUGHT")),
+    z.strictObject({ b: z.string() })
+  );
+
+  expect(schema.parse({ a: "x", b: "y" })).toEqual({ a: "x", b: "y" });
+});
+
+test("catch propagates a back-edge to whatever wraps it", () => {
+  // The memoizer marks a payload whose value is a node still being parsed. That mark has to survive the catch: an enclosing readonly must not freeze a half-built object, and the node's checks belong to the node itself rather than to the back-edge.
+  const Node: any = z.object({
+    get self() {
+      return z
+        .lazy(() => Node)
+        .catch(null)
+        .readonly()
+        .optional();
+    },
+  });
+  const cyclic: any = {};
+  cyclic.self = cyclic;
+  const frozen = Node.safeParse(cyclic);
+  expect(frozen.success).toBe(true);
+  expect(Object.keys(frozen.data)).toEqual(["self"]);
+
+  let checks = 0;
+  const Checked: any = z.object({
+    get self() {
+      return z
+        .lazy(() => Checked)
+        .catch(null)
+        .refine(() => {
+          checks++;
+          return true;
+        })
+        .optional();
+    },
+  });
+  const cyclic2: any = {};
+  cyclic2.self = cyclic2;
+  Checked.safeParse(cyclic2);
+  expect(checks).toBe(0);
+});
+
+test("a catch that fires does not rescue an issue from outside it", () => {
+  // The callback still runs and still computes its fallback — the inner schema really did fail. What it cannot do is answer for the unrecognized key the pipe forwarded past it, so the parse fails anyway.
+  let fired = 0;
+  const result = z
+    .strictObject({ a: z.string() })
+    .pipe(
+      z
+        .object({ a: z.string() })
+        .refine(() => false)
+        .catch(() => {
+          fired++;
+          return { a: "FALLBACK" };
+        })
+    )
+    .safeParse({ a: "x", extra: 1 });
+
+  expect(fired).toBe(1);
+  expect(result.success).toBe(false);
+  expect(result.error!.issues.map((i) => i.code)).toEqual(["unrecognized_keys"]);
+});
+
 test("direction-aware catch", () => {
   const schema = z.string().catch("fallback");

